package com.kuaixietech.commerce;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.kuaixietech.insurance.InsuranceSelections;
import com.kuaixietech.security.DomainAccessGuard;
import com.kuaixietech.service.finance.impl.AtomicMoneyService;
import com.kuaixietech.service.trading.support.IntentPricing;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.Date;
import java.time.LocalDate;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import static com.kuaixietech.commerce.ProductCheckoutModels.*;
/** Server-priced product checkout; available stock is decremented once in the escrow transaction. */
@Service
public class ProductCheckoutService {
 private final JdbcTemplate db;private final DomainAccessGuard guard;private final AtomicMoneyService money;private final InsuranceSelections insurance;private final ObjectMapper json;private final int hours;
 private static final String PRODUCT="SELECT p.id,p.owner_id,p.category_id,p.name,p.spec,p.region,p.note,p.price,p.stock,p.image_urls,p.status,s.carrier_verify_status,s.deleted_at,s.banned_until,sp.store_id,st.status AS store_status,st.owner_id AS store_owner FROM t_products p JOIN t_profiles s ON s.id=p.owner_id LEFT JOIN t_store_products sp ON sp.product_id=p.id LEFT JOIN t_stores st ON st.id=sp.store_id WHERE p.id=?";
 public ProductCheckoutService(JdbcTemplate db,DomainAccessGuard guard,AtomicMoneyService money,InsuranceSelections insurance,ObjectMapper json,@Value("${app.orders.intent-hours:24}") int hours){if(hours<1||hours>168)throw new IllegalArgumentException("intent-hours must be 1..168");this.db=db;this.guard=guard;this.money=money;this.insurance=insurance;this.json=json;this.hours=hours;}
 private Map<String,Object> row(String sql,Object...args){return db.queryForList(sql,args).stream().findFirst().orElse(null);}
 private static ResponseStatusException fail(HttpStatus status,String reason){return new ResponseStatusException(status,reason);}
 private static void changed(int rows){if(rows!=1)throw new IllegalStateException("PRODUCT_ORDER_CONCURRENT_CHANGE");}
 private static String uid(Object value){return value==null?null:value.toString().toLowerCase(Locale.ROOT);}
 private static BigDecimal decimal(Object value){return new BigDecimal(value.toString());}
 private String encoded(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("PRODUCT_ORDER_SNAPSHOT_FAILED");}}
 private Map<String,Object> visibleProduct(String id,String buyer,boolean locked){var p=row(PRODUCT+(locked?" FOR UPDATE":""),id);if(p==null||!"on".equals(p.get("status"))||!"approved".equals(p.get("carrier_verify_status"))||p.get("deleted_at")!=null||p.get("banned_until")!=null&&future(p.get("banned_until")))throw fail(HttpStatus.NOT_FOUND,"PRODUCT_UNAVAILABLE");p=new HashMap<>(p);p.put("owner_id",uid(p.get("owner_id")));p.put("store_owner",uid(p.get("store_owner")));if(buyer!=null&&buyer.equalsIgnoreCase(p.get("owner_id").toString()))throw fail(HttpStatus.BAD_REQUEST,"CANNOT_ORDER_OWN_PRODUCT");if(p.get("store_id")!=null&&(!"active".equals(p.get("store_status"))||!p.get("owner_id").equals(p.get("store_owner"))))throw fail(HttpStatus.NOT_FOUND,"PRODUCT_STORE_UNAVAILABLE");if(((Number)p.get("stock")).intValue()<1)throw fail(HttpStatus.CONFLICT,"PRODUCT_STOCK_UNAVAILABLE");return p;}
 private boolean future(Object value){java.time.LocalDateTime t=value instanceof java.sql.Timestamp timestamp?timestamp.toLocalDateTime():java.time.LocalDateTime.parse(value.toString().replace(' ','T'));return t.isAfter(java.time.LocalDateTime.now());}
 private Map<String,Object> eligibleTrip(Input input,Map<String,Object> product,boolean locked){var trip=row("SELECT id,owner_id,capacity_qty,remaining_slots,return_date,carry_mode FROM t_trips WHERE id=? AND owner_id=? AND status='active' AND visibility='public' AND verify_status='approved' AND carry_mode='solo' AND return_date>=CURRENT_DATE() AND (JSON_LENGTH(product_ids)=0 OR JSON_CONTAINS(product_ids,JSON_QUOTE(?)))"+(locked?" FOR UPDATE":""),input.tripId(),product.get("owner_id"),input.productId());if(trip==null||!"solo".equals(trip.get("carry_mode")))throw fail(HttpStatus.CONFLICT,"PRODUCT_TRIP_UNAVAILABLE");
  if(product.get("category_id")==null&&!db.queryForList("SELECT category_id FROM t_trip_categories WHERE trip_id=? LIMIT 1",input.tripId()).isEmpty())throw fail(HttpStatus.CONFLICT,"CATEGORY_REQUIRED_FOR_TRIP");
  if(product.get("category_id")!=null&&!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM t_categories c WHERE c.id=? AND c.active=1 AND (NOT EXISTS(SELECT 1 FROM t_trip_categories tc WHERE tc.trip_id=?) OR EXISTS(SELECT 1 FROM t_trip_categories tc WHERE tc.trip_id=? AND tc.category_id=c.id)))",Boolean.class,product.get("category_id"),input.tripId(),input.tripId())))throw fail(HttpStatus.CONFLICT,"CATEGORY_NOT_ALLOWED_FOR_TRIP");
  if(input.quantity()==null||input.quantity()<1||input.quantity()>100)throw fail(HttpStatus.BAD_REQUEST,"PRODUCT_QUANTITY_INVALID");Integer reserved=db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM t_orders WHERE trip_id=? AND status NOT IN('cancelled_no_fault','cancelled_breach','refunded','closed')",Integer.class,input.tripId());int remaining=Math.min(((Number)trip.get("remaining_slots")).intValue(),((Number)trip.get("capacity_qty")).intValue()-(reserved==null?0:reserved));if(input.quantity()>remaining)throw fail(HttpStatus.CONFLICT,"TRIP_CAPACITY_UNAVAILABLE");if(input.quantity()>((Number)product.get("stock")).intValue())throw fail(HttpStatus.CONFLICT,"PRODUCT_STOCK_UNAVAILABLE");
  if(input.expectDate()!=null&&(input.expectDate().isBefore(LocalDate.now())||input.expectDate().isBefore(asDate(trip.get("return_date")))))throw fail(HttpStatus.BAD_REQUEST,"PRODUCT_EXPECTED_DATE_BEFORE_TRIP_RETURN");return trip;
 }
 private LocalDate asDate(Object value){return value instanceof Date date?date.toLocalDate():LocalDate.parse(value.toString().substring(0,10));}
 private IntentPricing.Quote price(Input input,Map<String,Object> product,String buyer){var price=IntentPricing.externalQuote(decimal(product.get("price")).multiply(BigDecimal.valueOf(input.quantity())),input.insuranceChoice());if("yes".equals(input.insuranceChoice()))insurance.validate(buyer,input.insuranceQuoteId(),"trip",input.tripId(),price.goodsAmount(),product.get("name").toString());else if(input.insuranceQuoteId()!=null)throw fail(HttpStatus.BAD_REQUEST,"INSURANCE_SELECTION_CONFLICT");return price;}
 private String productFingerprint(Map<String,Object> p){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(Arrays.asList(p.get("id"),p.get("owner_id"),p.get("name"),p.get("spec"),p.get("region"),p.get("note"),Objects.toString(p.get("category_id"),null),decimal(p.get("price")).stripTrailingZeros().toPlainString(),p.get("store_id"),Objects.toString(p.get("image_urls"),"[]")))));}catch(Exception e){throw new IllegalStateException("PRODUCT_ORDER_HASH_FAILED");}}
 private Quote projection(Input input,Map<String,Object> product,IntentPricing.Quote price){return new Quote(input.productId(),input.tripId(),Objects.toString(product.get("store_id"),null),product.get("name").toString(),Objects.toString(product.get("spec"),null),decimal(product.get("price")).setScale(2).toPlainString(),input.quantity(),price.goodsAmount().toPlainString(),price.serviceFee().toPlainString(),price.insurancePremium().toPlainString(),price.buyerEscrow().toPlainString(),price.vendorDeposit().toPlainString(),price.currency(),price.pricingVersion(),hours,productFingerprint(product));}
 @Transactional(readOnly=true) public Quote quote(Input input){String buyer=guard.requireVerifiedBuyer();var product=visibleProduct(input.productId(),buyer,false);eligibleTrip(input,product,false);return projection(input,product,price(input,product,buyer));}
 public List<Map<String,Object>> trips(String id,int limit,int offset){if(limit<1||limit>100||offset<0)throw fail(HttpStatus.BAD_REQUEST,"PRODUCT_INVALID_PAGE");var p=visibleProduct(id,null,false);return db.queryForList("SELECT t.id,t.destination,t.depart_date,t.return_date,t.capacity_qty,LEAST(t.remaining_slots,GREATEST(t.capacity_qty-(SELECT COALESCE(SUM(o.quantity),0) FROM t_orders o WHERE o.trip_id=t.id AND o.status NOT IN('cancelled_no_fault','cancelled_breach','refunded','closed')),0)) AS remaining_slots FROM t_trips t WHERE t.owner_id=? AND t.status='active' AND t.visibility='public' AND t.verify_status='approved' AND t.carry_mode='solo' AND t.return_date>=CURRENT_DATE() AND (JSON_LENGTH(t.product_ids)=0 OR JSON_CONTAINS(t.product_ids,JSON_QUOTE(?))) AND ((? IS NULL AND NOT EXISTS(SELECT 1 FROM t_trip_categories restricted WHERE restricted.trip_id=t.id)) OR EXISTS(SELECT 1 FROM t_categories c WHERE c.id=? AND c.active=1 AND (NOT EXISTS(SELECT 1 FROM t_trip_categories tc WHERE tc.trip_id=t.id) OR EXISTS(SELECT 1 FROM t_trip_categories tc WHERE tc.trip_id=t.id AND tc.category_id=c.id)))) HAVING remaining_slots>0 ORDER BY t.depart_date,t.id LIMIT ? OFFSET ?",p.get("owner_id"),id,p.get("category_id"),p.get("category_id"),limit,offset);}
 private String hash(Input i){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(Arrays.asList(i.productId(),i.tripId(),i.quantity(),i.contactName().trim(),i.contactPhone().trim(),i.address().trim(),i.expectDate()==null?null:i.expectDate().toString(),i.note(),i.insuranceChoice(),i.insuranceQuoteId(),i.expectedUnitPrice().stripTrailingZeros().toPlainString(),i.expectedBuyerEscrow().stripTrailingZeros().toPlainString(),i.expectedProductFingerprint()))));}catch(Exception e){throw new IllegalStateException("PRODUCT_ORDER_HASH_FAILED");}}
 @Transactional(isolation=Isolation.READ_COMMITTED) public Map<String,String> create(Input input){String buyer=guard.requireVerifiedBuyer();if(input.requestId()==null||input.expectedUnitPrice()==null||input.expectedBuyerEscrow()==null||input.expectedProductFingerprint()==null)throw fail(HttpStatus.BAD_REQUEST,"PRODUCT_ORDER_CONFIRMATION_REQUIRED");String request;try{request=UUID.fromString(input.requestId()).toString();}catch(Exception e){throw fail(HttpStatus.BAD_REQUEST,"PRODUCT_ORDER_REQUEST_ID_INVALID");}String id=UUID.nameUUIDFromBytes(("product-order:"+buyer+":"+request).getBytes(StandardCharsets.UTF_8)).toString(),hash=hash(input);
  // Read only the immutable owner for lock ordering. Product/state/price are checked again after all locks.
  var owner=row("SELECT owner_id FROM t_products WHERE id=?",input.productId());var ids=new TreeSet<String>();ids.add(uid(buyer));if(owner!=null)ids.add(uid(owner.get("owner_id")));for(String uid:ids)if(row("SELECT id FROM t_profiles WHERE id=? FOR UPDATE",uid)==null)throw fail(HttpStatus.NOT_FOUND,"ACCOUNT_UNAVAILABLE");
  if(!buyer.equals(guard.requireVerifiedBuyer()))throw fail(HttpStatus.FORBIDDEN,"PRODUCT_ORDER_IDENTITY_CHANGED");
  // READ COMMITTED sees a concurrent retry's committed reservation after waiting on the buyer profile.
  var existing=row("SELECT r.request_hash,r.buyer_id,o.status FROM t_product_order_reservations r JOIN t_orders o ON o.id=r.order_id WHERE r.order_id=?",id);if(existing!=null){if(!buyer.equalsIgnoreCase(Objects.toString(existing.get("buyer_id"),""))||!hash.equals(existing.get("request_hash")))throw fail(HttpStatus.CONFLICT,"PRODUCT_ORDER_REQUEST_REUSED");return Map.of("id",id,"status",existing.get("status").toString());}
  if(owner==null)throw fail(HttpStatus.NOT_FOUND,"PRODUCT_UNAVAILABLE");var preview=visibleProduct(input.productId(),buyer,false);eligibleTrip(input,preview,true);
  if(preview.get("store_id")!=null){var store=row("SELECT id,owner_id,status FROM t_stores WHERE id=? FOR UPDATE",preview.get("store_id"));if(store==null||!"active".equals(store.get("status"))||!preview.get("owner_id").equals(uid(store.get("owner_id"))))throw fail(HttpStatus.CONFLICT,"PRODUCT_STORE_UNAVAILABLE");}
  var product=visibleProduct(input.productId(),buyer,true);if(!uid(owner.get("owner_id")).equals(product.get("owner_id"))||!Objects.equals(preview.get("store_id"),product.get("store_id")))throw fail(HttpStatus.CONFLICT,"PRODUCT_CHANGED_REQUOTE");eligibleTrip(input,product,false);if(!productFingerprint(product).equals(input.expectedProductFingerprint()))throw fail(HttpStatus.CONFLICT,"PRODUCT_CHANGED_REQUOTE");var price=price(input,product,buyer);if(decimal(product.get("price")).compareTo(input.expectedUnitPrice())!=0||price.buyerEscrow().compareTo(input.expectedBuyerEscrow())!=0)throw fail(HttpStatus.CONFLICT,"PRICE_CHANGED_RECONFIRM_QUOTE");if(input.quantity()>((Number)product.get("stock")).intValue())throw fail(HttpStatus.CONFLICT,"PRODUCT_STOCK_UNAVAILABLE");BigDecimal balance=money.lockBalance(buyer);if(balance==null||balance.compareTo(price.buyerEscrow())<0)throw fail(HttpStatus.CONFLICT,"INSUFFICIENT_BALANCE");
  var snapshot=new LinkedHashMap<String,Object>();snapshot.put("pricing_version",IntentPricing.EXTERNAL_VERSION);snapshot.put("request_hash",hash);snapshot.put("product_id",input.productId());snapshot.put("store_id",product.get("store_id"));snapshot.put("unit_price",decimal(product.get("price")).toPlainString());snapshot.put("insurance_choice",input.insuranceChoice());snapshot.put("insurance_quote_id",input.insuranceQuoteId());snapshot.put("insurance_escrow",BigDecimal.ZERO);snapshot.put("buyer_escrow",price.buyerEscrow());String agreed=encoded(snapshot);
  changed(db.update("UPDATE t_products SET stock=stock-?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=? AND stock>=?",input.quantity(),input.productId(),input.quantity()));
  changed(db.update("INSERT INTO t_orders(id,order_no,trip_id,buyer_id,vendor_id,source,item_name,item_spec,quantity,unit,expect_unit_price,goods_amount,service_fee,buyer_deposit,vendor_deposit,status,buyer_deposit_status,vendor_deposit_status,insured,insurance_premium,declared_value,contact_name,contact_phone,address,note,expect_arrive_date,intent_deadline,agreed_json,ref_image_urls,purchase_receipt_urls,cancel_proof_urls,purchase_evidence,freight_label_urls,ship_risk_flags,purchase_meta,purchase_risk_flags) VALUES(?,?,?,?,?,'product_order',?,?,?,'piece',?,?,?,?,?,'requesting','frozen','unpaid',?,0,?,?,?,?,?,?,TIMESTAMPADD(HOUR,?,CURRENT_TIMESTAMP(3)),CAST(? AS JSON),CAST(? AS JSON),JSON_ARRAY(),JSON_ARRAY(),JSON_OBJECT(),JSON_ARRAY(),JSON_ARRAY(),JSON_OBJECT(),JSON_ARRAY())",id,"DD"+id.replace("-",""),input.tripId(),buyer,product.get("owner_id"),product.get("name"),product.get("spec"),input.quantity(),decimal(product.get("price")),price.goodsAmount(),price.serviceFee(),price.buyerEscrow(),price.vendorDeposit(),"yes".equals(input.insuranceChoice())?"unselected":"waived",price.goodsAmount(),input.contactName().trim(),input.contactPhone().trim(),input.address().trim(),input.note(),input.expectDate(),hours,agreed,Objects.toString(product.get("image_urls"),"[]")));
  if(money.addBalance(buyer,price.buyerEscrow().negate(),"deposit_freeze",id,"商品下单托管：货款及5%服务费；保险由机构另行收取")==null)throw new IllegalStateException("PRODUCT_ORDER_BALANCE_CHANGED");changed(db.update("INSERT INTO t_deposits(id,order_id,payer_id,party_role,kind,amount,status) VALUES(?,?,?,'buyer','buyer_escrow',?,'frozen')",UUID.randomUUID().toString(),id,buyer,price.buyerEscrow()));
  changed(db.update("INSERT INTO t_product_order_reservations(order_id,product_id,buyer_id,vendor_id,trip_id,store_id,quantity,unit_price,goods_amount,service_fee,currency,stock_state,request_hash,snapshot) VALUES(?,?,?,?,?,?,?,?,?,?,'CNY','held',?,CAST(? AS JSON))",id,input.productId(),buyer,product.get("owner_id"),input.tripId(),product.get("store_id"),input.quantity(),decimal(product.get("price")),price.goodsAmount(),price.serviceFee(),hash,agreed));return Map.of("id",id,"status","requesting");
 }
}
